class GymMember{protected String memberId;protected int monthlyFee;private int sessionsAttended;public GymMember(String id,int fee){if(id==null||id.trim().length()<4)throw new IllegalArgumentException("Invalid member ID");if(fee<=0)throw new IllegalArgumentException("Fee must be positive");memberId=id;monthlyFee=fee;sessionsAttended=0;}public void attendSession(){sessionsAttended++;}public int getSessionsAttended(){return sessionsAttended;}public void displayInfo(){System.out.println("Standard Member | Sessions: "+sessionsAttended);}}
class PremiumMember extends GymMember{private String trainerName;public PremiumMember(String id,int fee,String t){super(id,fee);trainerName=t;}public String getTrainerName(){return trainerName;}public void displayInfo(){System.out.println("Premium Member | Trainer: "+trainerName+" | Sessions: "+getSessionsAttended());}}
public class GymSignUpDemo{static String signUpBatch(String[] ids,int fee){int ok=0,no=0;for(String id:ids)try{new GymMember(id,fee);ok++;}catch(IllegalArgumentException e){no++;}return "Signed Up: "+ok+" | Rejected: "+no;}public static void main(String[] args){try{new GymMember("GM1",1000);}catch(IllegalArgumentException e){System.out.println("Construction rejected");}PremiumMember p=new PremiumMember("MEM01",2000,"Coach Riya");p.attendSession();p.attendSession();System.out.println(p.getSessionsAttended());String[] ids={"MEM1","GM1","MEM2"," ","MEM3"};System.out.println(signUpBatch(ids,1000));}}